import numpy as np

def center(size, l, x, y):
  for i in range(size):
    for j in range(size):
      l[i+size+x][j+size+y] = '.'


n = int(input())

size = 3**n
size_low = 3**(n-1)

l0 = np.array([
  ['#', '#', '#'],
  ['#', '.', '#'],
  ['#', '#', '#']
])

lk = [['#' for i in range(size)] for j in range(size)]

if n == 0:
  print('#')
elif n == 1:
  for i in l0:
    print(*i, sep='')
else:
  def create_carpet(lk, size, x, y, level):
    if level == 0:
      lk[x][y] = '#'
      return
    block_size = size // 3
    for i in range(3):
      for j in range(3):
        if i == 1 and j == 1:
          for a in range(block_size):
            for b in range(block_size):
              lk[x + i * block_size + a][y + j * block_size + b] = '.'
        else:
          create_carpet(lk, block_size, x + i * block_size, y + j * block_size, level - 1)

  create_carpet(lk, size, 0, 0, n)


  # Removed unnecessary calls to center function


  for i in lk:
    print(*i,sep='')

